insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'Diriwayatkan dari Abu Ubaid (ra):');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'Aku menghadiri salat Id bersama Umar. Beliau mengerjakan salat sebelum khotbah, lalu berkata: Sesungguhnya Rasulullah shallallahu alaihi wasallam melarang berpuasa pada dua hari ini. Adapun Iduladha, kamu makan daging kurbanmu; adapun Idulfitri, kamu berbuka dari puasamu.');
