insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'Diriwayatkan dari Abu Qatada (ra), bahwa Rasulullah shallallahu alaihi wasallam bersabda:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'Puasa hari Arafah, aku berharap kepada Allah agar menghapus dosa setahun yang lalu dan setahun yang akan datang; dan puasa hari Asyura, aku berharap kepada Allah agar menghapus dosa setahun yang lalu.');
