insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'Salah seorang istri Nabi shallallahu alaihi wasallam berkata:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'Rasulullah shallallahu alaihi wasallam biasa berpuasa pada sembilan hari pertama Zulhijah, hari Asyura, dan tiga hari setiap bulan.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].hadith', '2417');
