insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[2].title', 'Sembilan Hari Pertama Zulhijah');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Diriwayatkan dari Abdullah bin Amr bin Ash (ra), ia berkata: Rasulullah shallallahu alaihi wasallam bersabda kepadaku:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Cukuplah bagimu berpuasa tiga hari setiap bulan, karena setiap kebaikan dibalas sepuluh kali lipat; dengan demikian, itu seperti puasa sepanjang tahun.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Diriwayatkan dari Abu Qatada (ra), bahwa Rasulullah shallallahu alaihi wasallam bersabda:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Puasa tiga hari setiap bulan, serta Ramadan hingga Ramadan berikutnya, adalah puasa sepanjang masa.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'Rasulullah shallallahu alaihi wasallam bersabda kepada Abu Zar:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'Barang siapa berpuasa tiga hari setiap bulan, maka itu seperti puasa sepanjang masa.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].hadith', '1708');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[4].intro', 'Diriwayatkan dari Jarir bin Abdullah (ra), dari Nabi shallallahu alaihi wasallam, beliau bersabda:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Puasa tiga hari setiap bulan adalah puasa sepanjang masa, dan hari-hari putih, yaitu tanggal tiga belas, empat belas, dan lima belas.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'Diriwayatkan dari Abu Hurairah (ra), ia berkata:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Kekasihku, Nabi Muhammad shallallahu alaihi wasallam, berwasiat kepadaku dengan tiga perkara: puasa tiga hari setiap bulan, salat Duha dua rakaat, dan salat Witir sebelum tidur.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'Abu Darda (ra) berkata:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Kekasihku, Nabi shallallahu alaihi wasallam, berpesan kepadaku tiga perkara yang tidak akan kutinggalkan karena apa pun: beliau berpesan kepadaku untuk berpuasa tiga hari setiap bulan.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'Nabi Muhammad shallallahu alaihi wasallam menasihati Abu Zar (ra):');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Jika engkau berpuasa pada sebagian bulan, maka puasalah pada tanggal tiga belas, empat belas, dan lima belas.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].id', 'fasting-reason-white-days');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[3].title', 'Hari-hari Putih');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Diriwayatkan dari Usamah bin Zaid (ra), bahwa Rasulullah shallallahu alaihi wasallam bersabda:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Itulah dua hari ketika amalan dihadapkan kepada Tuhan seluruh alam, dan aku ingin amalanku dihadapkan dalam keadaan berpuasa.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'Nabi shallallahu alaihi wasallam ditanya oleh Abu Qatada al-Anshari (ra) tentang puasa hari Senin, lalu beliau menjawab:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'Itulah hari aku dilahirkan, hari aku diutus, atau hari wahyu diturunkan kepadaku.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].hadith', '1162b');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[3].intro', 'Diriwayatkan dari Aisyah (ra), ia berkata:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[3].quote', 'Nabi shallallahu alaihi wasallam sangat memperhatikan puasa hari Senin dan Kamis.');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].hadith', '745');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[0].intro', 'Pernyataan ini diriwayatkan dari Abu Hurairah (ra), bahwa Rasulullah shallallahu alaihi wasallam bersabda:');
insert into i18n_bundles (locale, code, value) values ('in', 'fasting.reason-groups.voluntary.reasons[4].cites[0].quote', 'Amal-amal dihadapkan pada hari Senin dan Kamis, dan aku ingin amalanku dihadapkan dalam keadaan berpuasa.');
